256→          if (idleTimer) { clearTimeout(idleTimer); }
257→          idleTimer = setTimeout(() => {
258→            console.error(`[sidecar] SDK idle timeout (${SDK_IDLE_TIMEOUT_MS}ms) reached, aborting reqId=${requestId}`);
